import{_ as t}from"./chunks/Audio.COine8Wh.js";import{c as a,o as n,j as i,G as r,ae as o,a as s}from"./chunks/framework.Bw0Gm4PQ.js";const f=JSON.parse('{"title":"FIGHTING OVERCRIMINALIZATION IN FEDERAL REGULATIONS","description":"","frontmatter":{"legisId":"2025-05-09-fighting-overcriminalization-in-federal-regulations","title":"FIGHTING OVERCRIMINALIZATION IN FEDERAL REGULATIONS","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/05/fighting-overcriminalization-in-federal-regulations/","publishDate":"2025-05-09T18:09:02-04:00","head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Executive Orders\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"FIGHTING OVERCRIMINALIZATION IN FEDERAL REGULATIONS\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders/2025-05-09-fighting-overcriminalization-in-federal-regulations\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"FIGHTING OVERCRIMINALIZATION IN FEDERAL REGULATIONS\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/executive-orders/2025-05-09-fighting-overcriminalization-in-federal-regulations\\",\\"datePublished\\":\\"2025-05-09T18:09:02-04:00\\",\\"dateModified\\":1768439847000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/executive-orders/2025-05-09-fighting-overcriminalization-in-federal-regulations\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"executive-orders/2025-05-09-fighting-overcriminalization-in-federal-regulations.md","filePath":"executive-orders/2025-05-09-fighting-overcriminalization-in-federal-regulations.md","lastUpdated":1768439847000}'),l={name:"executive-orders/2025-05-09-fighting-overcriminalization-in-federal-regulations.md"},p=Object.assign(l,{setup(d){return(g,e)=>(n(),a("div",null,[e[0]||(e[0]=i("h1",{id:"fighting-overcriminalization-in-federal-regulations",tabindex:"-1"},[s("FIGHTING OVERCRIMINALIZATION IN FEDERAL REGULATIONS "),i("a",{class:"header-anchor",href:"#fighting-overcriminalization-in-federal-regulations","aria-label":'Permalink to "FIGHTING OVERCRIMINALIZATION IN FEDERAL REGULATIONS"'},"​")],-1)),r(t),e[1]||(e[1]=o('<p>Published on Friday, May 9, 2025</p><ul><li>The U.S. is highly overregulated, with over 48,000 sections in the Code of Federal Regulations, complicating compliance and understanding.</li><li>Many regulations carry potential criminal penalties, with an estimated hundreds of thousands of regulatory crimes.</li><li>Strict liability offenses allow for criminal convictions without proof of intent, unfairly affecting average citizens.</li><li>The executive branch is both writing and enforcing laws, which risks abuse and favors large corporations over individuals.</li><li>The order aims to reduce regulatory burdens, ensuring individuals are not unknowingly made criminals.</li></ul><p><strong>Policies Established:</strong></p><ul><li>Criminal enforcement of regulatory offenses is discouraged.</li><li>Prosecutions should target individuals who knowingly violate regulations and cause significant harm.</li><li>Strict liability offenses are generally disfavored, with agencies encouraged to use civil enforcement instead.</li><li>Agencies must clearly state regulations that carry criminal penalties, including applicable mens rea standards.</li></ul><p><strong>Reporting Requirements:</strong></p><ul><li>Agency heads must report all criminal regulatory offenses and associated penalties to the Office of Management and Budget (OMB) within one year.</li><li>The report should be publicly accessible and updated annually.</li><li>Criminal enforcement is discouraged for offenses not listed in the report.</li></ul><p><strong>Rulemaking Procedures:</strong></p><ul><li>Notices of proposed rulemaking (NPRMs) must indicate when a regulation constitutes a criminal regulatory offense.</li><li>Regulatory text must specify a mens rea requirement for criminal offenses.</li><li>Proposed strict liability offenses are deemed significant and require further review.</li></ul><p><strong>Mens Rea Standard:</strong></p><ul><li>Agencies are to assess if they can adopt a generalized mens rea standard for criminal regulatory offenses.</li><li>Agencies must submit a report proposing changes to applicable mens rea standards within 30 days of the initial report.</li></ul><p><strong>Guidance Publication:</strong></p><ul><li>Within 45 days, agencies must publish guidance on addressing regulatory offenses, considering factors like harm caused and the defendant&#39;s awareness of the violation.</li></ul><p><strong>Exemptions:</strong></p><ul><li>The order does not apply to immigration laws or regulations related to national security/defense.</li></ul><p><strong>General Provisions:</strong></p><ul><li>The order does not impair existing legal authorities or create enforceable rights against the U.S. or its entities.</li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/05/fighting-overcriminalization-in-federal-regulations/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/05/fighting-overcriminalization-in-federal-regulations/</a></p>',17))]))}});export{f as __pageData,p as default};
